int* elegir(std::array<int, 3>& datos, int indice) {
    if (indice < 0 || indice > 2) {
        return nullptr;
    }

    return &datos.at(static_cast<std::size_t>(indice));
}

int main() {
    std::array<int, 3> datos{2, 5, 8};
    int* elegido = elegir(datos, 2);

    if (elegido != nullptr) {
        *elegido = 7;
    }
    int* ausente = elegir(datos, -1);
    std::cout << datos[2] << ':' << (ausente == nullptr);

    return 0;
}

