            actual = elegir(datos, argumento);
            if (actual == nullptr) {
                estado = "Indice invalido";
            } else {
                estado = "Elegido";
            }
        } else if (operacion == 2) {
            if (actual == nullptr) {
                estado = "Sin seleccion";
            } else if (argumento < 0 || argumento > 9) {
                estado = "Rechazo";
            } else {
                *actual = argumento;
                estado = "Cambio";
            }
        } else if (operacion == 3) {
            guardado = actual;
            estado = "Guardado";
        } else if (operacion == 4) {
            actual = nullptr;
            estado = "Sin seleccion";
        } else if (operacion == 5) {
            if (guardado == nullptr) {
                estado = "Sin guardado";
            } else if (argumento < 0 || argumento > 9) {
                estado = "Rechazo";
            } else {
                *guardado = argumento;
                estado = "Cambio";
            }
        } else {
            estado = "Operacion invalida";
        }
        std::cout << estado << ";Actual:";
        if (actual == nullptr) {
            std::cout << 'X';
        } else {
            std::cout << *actual;
        }
        std::cout << ";Guardado:";
        if (guardado == nullptr) {
            std::cout << 'X';
        } else {
            std::cout << *guardado;
        }
        std::cout << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << '\n';
    }

    return 0;
}

